void Logger::Log(Event::Ptr event) noexcept
{
    if (event->Level() >= GetLevel())
    {
        for (const auto& appender : appenders_)
        {
            appender->Log(*this, *event);
        }
    }
}

std::string Formatter::Format(const Logger& logger, const Event& event) const noexcept
{
    // フォーマット文字列に基づいてイベント情報を変換するロジックを実装する。
    std::ostringstream oss;
    oss << "[" << log::LevelToString(event.Level()) << "] [" << event.FileName() << ":" << event.LineNum() << "] [Thread:" << event.ThreadId() << "] " << event.Message();
    return oss.str();
}

void Appender::Log(const Logger& logger, const Event& event) noexcept
{
    auto formatted_message = formatter_->Format(logger, event);
    // 形式化されたメッセージを適切な出力先に記録するロジックを実装する。
}

void StdOutAppender::Log(const Logger& logger, const Event& event) noexcept
{
    auto formatted_message = formatter_->Format(logger, event);
    std::cout << formatted_message;
}

void FileAppender::Log(const Logger& logger, const Event& event) noexcept
{
    auto formatted_message = formatter_->Format(logger, event);
    // ファイルにメッセージを書き込むロジックを実装する。
}

#pragma once
#include <string>
#include <string_view>
#include <memory>
#include <vector>
#include <optional>
#include <sstream>
#include "log/Level.h"
#include "Event.h"
#include "Formatter.h"
#include "Appender.h"

class Logger
{
public:
    std::string_view Name() const noexcept;
    std::size_t Capacity() const noexcept;
    log::Level GetLevel() const noexcept;
    void SetLevel(log::Level level) noexcept;
    Formatter::Ptr GetDefaultFormatter() const noexcept;
    void SetDefaultFormatter(Formatter::Ptr formatter) noexcept;
    void SetDefaultFormatter(std::string_view pattern);
    std::string ToYamlString() const noexcept;
    void Log(Event::Ptr event) noexcept;
    void AddAppender(Appender::Ptr appender) noexcept;
    void RemoveAppender(Appender::Ptr appender) noexcept;
    void ClearAppenders() noexcept;

private:
    std::string name_;
    std::size_t capacity_;
    log::Level level_;
    Formatter::Ptr formatter_;
    std::vector<Appender::Ptr> appenders_;
};

#pragma once
#include <string>
#include <string_view>
#include <memory>
#include "log/Level.h"
#include "Event.h"

class Formatter
{
public:
    virtual std::string Format(const Logger& logger, const Event& event) const noexcept = 0;
    virtual std::string_view Pattern() const noexcept = 0;
};
typedef std::shared_ptr<Formatter> FormatterPtr;
